cd /workspace && python3 - <<'PY'
import json,subprocess
fx=json.load(open('examples/checks.json'))
for i,f in enumerate(fx):
    raw=f.get('raw')
    if raw is None: raw=json.dumps(f['request'],separators=(',',':'))
    p=subprocess.run(['python3','-B','submission/main.py'],input=raw.encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    print(i,p.returncode,len(p.stdout),p.stdout[:200],p.stderr[:200])
    try:
      got=json.loads(p.stdout)
      print('MATCH',got==f['response'])
      if got!=f['response']:print('GOT',json.dumps(got)[:1000])
    except Exception as e: print(e)
PY
